package net.civeira.phylax.features.document.template.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.TemplateBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class TemplateBatchController implements TemplateBatchApi {

  /**
   * Template
   *
   * @autogenerated BatchControllerGenerator
   */
  private final TemplateDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final TemplateDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final TemplateEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response templateApiBatchDelete(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return deleteController.templateApiBatchDelete(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response templateApiBatchDeleteQuery(final String batchId) {
    return deleteController.templateApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response templateApiBatchDisable(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return disableController.templateApiBatchDisable(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response templateApiBatchDisableQuery(final String batchId) {
    return disableController.templateApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response templateApiBatchEnable(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return enableController.templateApiBatchEnable(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response templateApiBatchEnableQuery(final String batchId) {
    return enableController.templateApiBatchEnableQuery(batchId);
  }
}
